import { useState } from 'react'

interface WorkItemMetadata {
  additions?: number
  deletions?: number
  reviewers?: string[]
  issue_type?: string
  story_points?: number
  labels?: string[]
  pr_number?: number
  sha?: string
}

interface WorkItem {
  id: string
  datasource: string
  event_type: string
  external_id: string
  project: string
  title: string
  description?: string | null
  status: string
  timestamp: string
  url: string
  metadata?: WorkItemMetadata | null
}

interface WorkItemCardProps {
  item: WorkItem
  compact?: boolean
}

function DatasourceBadge({ datasource }: { datasource: string }) {
  if (datasource === 'jira') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-700">Jira</span>
  }
  if (datasource === 'launchpad') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-orange-100 text-orange-700">LP</span>
  }
  return <span className="inline-block px-1.5 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-600">GH</span>
}

function StatusBadge({ status }: { status: string }) {
  const lower = status.toLowerCase()
  if (lower === 'merged' || lower === 'done' || lower === 'closed') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs bg-green-100 text-green-700">{status}</span>
  }
  if (lower === 'draft') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs bg-yellow-100 text-yellow-700">{status}</span>
  }
  if (lower === 'open' || lower === 'in progress') {
    return <span className="inline-block px-1.5 py-0.5 rounded text-xs bg-blue-100 text-blue-700">{status}</span>
  }
  return <span className="inline-block px-1.5 py-0.5 rounded text-xs bg-gray-100 text-gray-600">{status}</span>
}

function relativeTime(timestamp: string): string {
  const date = new Date(timestamp)
  const now = new Date()
  const diffMs = now.getTime() - date.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  const diffHours = Math.floor(diffMs / 3600000)
  const diffDays = Math.floor(diffMs / 86400000)
  if (diffMins < 60) return `${diffMins}m ago`
  if (diffHours < 24) return `${diffHours}h ago`
  if (diffDays < 30) return `${diffDays}d ago`
  return date.toLocaleDateString()
}

export default function WorkItemCard({ item, compact = false }: WorkItemCardProps) {
  const [expanded, setExpanded] = useState(false)
  const { datasource, event_type, external_id, project, title, description, status, timestamp, url, metadata } = item

  let iconLabel = ''
  if (event_type === 'pull_request') iconLabel = 'PR'
  else if (event_type === 'issue') iconLabel = 'Issue'
  else if (event_type === 'commit') iconLabel = 'Commit'
  else if (event_type === 'pull_request_review') iconLabel = 'Review'
  else iconLabel = event_type

  const chips: string[] = []
  if (metadata?.additions !== undefined && metadata?.deletions !== undefined) {
    chips.push(`+${metadata.additions} -${metadata.deletions}`)
  }
  if (metadata?.story_points !== undefined) {
    chips.push(`${metadata.story_points} pts`)
  }
  if (metadata?.issue_type) {
    chips.push(metadata.issue_type)
  }
  if (metadata?.reviewers && metadata.reviewers.length > 0) {
    chips.push(`${metadata.reviewers.length} reviewers`)
  }

  const maxDescLen = compact ? 60 : 120
  const truncatedDesc = description && description.length > maxDescLen
    ? description.slice(0, maxDescLen) + '...'
    : description

  if (compact) {
    return (
      <div className="flex items-center gap-2 text-sm py-1.5 px-2 hover:bg-gray-50 rounded">
        <DatasourceBadge datasource={datasource} />
        <span className="text-gray-500 text-xs">{iconLabel} #{external_id}</span>
        <span className="flex-1 truncate text-gray-900">{title}</span>
        <StatusBadge status={status} />
        <span className="text-xs text-gray-400">{relativeTime(timestamp)}</span>
        {url && (
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-blue-600 hover:text-blue-800 text-xs"
            onClick={(e) => e.stopPropagation()}
          >
            ↗
          </a>
        )}
      </div>
    )
  }

  return (
    <div className="border border-gray-200 rounded-lg p-3 bg-white hover:shadow-sm transition-shadow">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2">
          <DatasourceBadge datasource={datasource} />
          <span className="text-xs text-gray-500">{project}</span>
        </div>
        <StatusBadge status={status} />
      </div>

      <div className="mt-1.5">
        <h4 className="text-sm font-medium text-gray-900">{title}</h4>
      </div>

      {truncatedDesc && (
        <p
          className="mt-1 text-xs text-gray-500 cursor-pointer"
          onClick={() => setExpanded(!expanded)}
        >
          {expanded ? description : truncatedDesc}
          {description && description.length > maxDescLen && (
            <span className="text-blue-600 ml-1">{expanded ? 'Show less' : 'Show more'}</span>
          )}
        </p>
      )}

      <div className="mt-2 flex items-center justify-between gap-2">
        <div className="flex items-center gap-2 text-xs text-gray-500">
          <span>{iconLabel} #{external_id}</span>
          <span>•</span>
          <span>{relativeTime(timestamp)}</span>
          {chips.length > 0 && (
            <>
              <span>•</span>
              <span>{chips.join(' • ')}</span>
            </>
          )}
        </div>
        {url && (
          <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-blue-600 hover:text-blue-800 flex items-center gap-0.5"
          >
            Open <span className="text-xs">↗</span>
          </a>
        )}
      </div>
    </div>
  )
}

import { useState } from 'react'
import { useCommits } from '../hooks/useMetrics'

interface CommitItem {
  id: string
  sha: string
  message: string
  timestamp: string
  url: string
  project: string
  pr_number?: number | null
}

interface CommitListProps {
  personId: string
  totalCommits: number
  prCount: number
  from?: string
  to?: string
}

function relativeTime(timestamp: string): string {
  const date = new Date(timestamp)
  const now = new Date()
  const diffMs = now.getTime() - date.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  const diffHours = Math.floor(diffMs / 3600000)
  const diffDays = Math.floor(diffMs / 86400000)
  if (diffMins < 60) return `${diffMins}m ago`
  if (diffHours < 24) return `${diffHours}h ago`
  if (diffDays < 30) return `${diffDays}d ago`
  return date.toLocaleDateString()
}

function formatDate(timestamp: string): string {
  const date = new Date(timestamp)
  return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
}

export default function CommitList({ personId, totalCommits, prCount, from, to }: CommitListProps) {
  const [expanded, setExpanded] = useState(false)

  const { data, isLoading, error } = useCommits(personId, {
    from,
    to,
    page: 1,
    per_page: 100,
  })

  if (totalCommits === 0) {
    return null
  }

  const commits: CommitItem[] = data?.items || []

  const grouped: Record<string, CommitItem[]> = {}
  for (const commit of commits) {
    const day = formatDate(commit.timestamp)
    if (!grouped[day]) grouped[day] = []
    grouped[day].push(commit)
  }

  return (
    <div className="border border-gray-200 rounded-lg overflow-hidden">
      <button
        className="w-full flex items-center justify-between px-4 py-3 bg-gray-50 hover:bg-gray-100 text-left"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-2">
          <span className="font-medium text-gray-900">{totalCommits} commits</span>
          <span className="text-sm text-gray-500">across {prCount} PRs</span>
        </div>
        <span className="text-gray-400">{expanded ? '▾' : '▸'}</span>
      </button>

      {expanded && (
        <div className="border-t border-gray-200">
          {isLoading && (
            <div className="p-4 text-center text-gray-400 text-sm">Loading commits...</div>
          )}
          {error && (
            <div className="p-4 text-center text-red-600 text-sm">Failed to load commits</div>
          )}
          {!isLoading && !error && Object.entries(grouped).map(([day, dayCommits]) => (
            <div key={day} className="border-b border-gray-100 last:border-b-0">
              <div className="px-4 py-2 bg-gray-50 text-xs font-medium text-gray-600">
                {day} • {dayCommits.length} commits
              </div>
              <div className="divide-y divide-gray-100">
                {dayCommits.slice(0, 5).map((commit) => (
                  <div key={commit.id} className="flex items-center gap-3 px-4 py-2 hover:bg-gray-50">
                    <code className="text-xs text-gray-500 font-mono">{commit.sha}</code>
                    <span className="flex-1 text-sm text-gray-700 truncate">{commit.message}</span>
                    {commit.pr_number && (
                      <span className="text-xs text-gray-400">PR #{commit.pr_number}</span>
                    )}
                    {commit.url && (
                      <a
                        href={commit.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-xs text-blue-600 hover:text-blue-800"
                        onClick={(e) => e.stopPropagation()}
                      >
                        ↗
                      </a>
                    )}
                  </div>
                ))}
                {dayCommits.length > 5 && (
                  <div className="px-4 py-2 text-xs text-gray-400 text-center">
                    ... {dayCommits.length - 5} more commits
                  </div>
                )}
              </div>
            </div>
          ))}
          {commits.length > 0 && commits[0]?.url && (
            <div className="px-4 py-2 bg-gray-50 border-t border-gray-200">
              <a
                href={commits[0].url.replace(/\/commit\/.+$/, '/commits')}
                target="_blank"
                rel="noopener noreferrer"
                className="text-sm text-blue-600 hover:text-blue-800"
              >
                View all commits on GitHub ↗
              </a>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { useSearchParams } from 'react-router-dom'

type ViewMode = 'grouped' | 'timeline'

interface ViewToggleProps {
  defaultValue?: ViewMode
}

export default function ViewToggle({ defaultValue = 'grouped' }: ViewToggleProps) {
  const [searchParams, setSearchParams] = useSearchParams()
  const currentView = (searchParams.get('view') as ViewMode) || defaultValue

  const setView = (view: ViewMode) => {
    const newParams = new URLSearchParams(searchParams)
    newParams.set('view', view)
    setSearchParams(newParams, { replace: true })
  }

  return (
    <div className="inline-flex rounded-md border border-gray-300 overflow-hidden">
      <button
        className={`px-3 py-1.5 text-sm font-medium ${
          currentView === 'grouped'
            ? 'bg-gray-900 text-white'
            : 'bg-white text-gray-700 hover:bg-gray-50'
        }`}
        onClick={() => setView('grouped')}
      >
        Grouped
      </button>
      <button
        className={`px-3 py-1.5 text-sm font-medium border-l border-gray-300 ${
          currentView === 'timeline'
            ? 'bg-gray-900 text-white'
            : 'bg-white text-gray-700 hover:bg-gray-50'
        }`}
        onClick={() => setView('timeline')}
      >
        Timeline
      </button>
    </div>
  )
}

