interface WorkItem {
  id: string
  datasource: string
  event_type: string
  external_id: string
  project: string
  title: string
  description?: string | null
  status: string
  timestamp: string
  url: string
  metadata?: {
    additions?: number
    deletions?: number
    reviewers?: string[]
    issue_type?: string
    story_points?: number
    labels?: string[]
    pr_number?: number
    sha?: string
  } | null
}

interface WorkItemsSectionProps {
  personId: string
  from?: string
  to?: string
  sprintId?: string
}

export default function WorkItemsSection({ personId, from, to, sprintId }: WorkItemsSectionProps) {
  const [searchParams] = useSearchParams()
  const sectionRef = useRef<HTMLDivElement>(null)
  const [collapsed, setCollapsed] = useState(false)

  const view = searchParams.get('view') || 'grouped'
  const shouldScroll = searchParams.get('section') === 'work-items'

  useEffect(() => {
    if (shouldScroll && sectionRef.current) {
      sectionRef.current.scrollIntoView({ behavior: 'smooth' })
    }
  }, [shouldScroll])

  const { data, isLoading, error } = useWorkItems(personId, {
    status: 'completed',
    from,
    to,
    per_page: 100,
  })

  const items: WorkItem[] = data?.items || []
  const total = data?.total || 0

  const timeframeLabel = sprintId
    ? `Sprint`
    : from && to
      ? `${from} – ${to}`
      : 'Last 30 days'

  return (
    <div ref={sectionRef} className="mt-8">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-3">
