          >
            <span>{collapsed ? '▸' : '▾'}</span>
          </button>
          <h2 className="text-lg font-semibold text-gray-900">Work Items</h2>
          <span className="text-sm text-gray-500">{timeframeLabel}</span>
          <span className="text-sm text-gray-400">• {total} items</span>
